class Solution {
    public int longestValidParentheses(String s) {
        int max = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 2; j <= n; j += 2) {
                if (isValid(s, i, j)) {
                    max = Math.max(max, j - i);
                }
            }
        }
        return max;
    }
    private boolean isValid(String s, int start, int end) {
        int bal = 0;
        for (int k = start; k < end; k++) {
            if (s.charAt(k) == '(') bal++;
            else bal--;
            if (bal < 0) return false;
        }
        return bal == 0;
    }
}

