    public int sumSubarrayMins(int[] arr) {
        int n = arr.length;
        int mod = 1_000_000_007;
        int[] left = new int[n];
        int[] right = new int[n];
        Stack<Integer> s1 = new Stack<>();
        Stack<Integer> s2 = new Stack<>();
        for (int i = 0; i < n; i++) {
            while (!s1.isEmpty() && arr[s1.peek()] >= arr[i]) s1.pop();
            left[i] = s1.isEmpty() ? i + 1 : i - s1.peek();
            s1.push(i);
        }
        for (int i = n - 1; i >= 0; i--) {
            while (!s2.isEmpty() && arr[s2.peek()] > arr[i]) s2.pop();
            right[i] = s2.isEmpty() ? n - i : s2.peek() - i;
            s2.push(i);
        }
        long sum = 0;
        for (int i = 0; i < n; i++) {
            long count = ((long) left[i] * right[i]) % mod;
            sum = (sum + count * arr[i]) % mod;
        }
        return (int) sum;
    }
}

