class Solution {
    public int longestSubarray(int[] nums, int limit) {
        int maxLen = 0;
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            int min = nums[i], max = nums[i];
            for (int j = i; j < n; j++) {
                if (nums[j] < min) min = nums[j];
                if (nums[j] > max) max = nums[j];
                if (max - min <= limit) {
                    maxLen = Math.max(maxLen, j - i + 1);
                } else {
                    break;
                }
            }
        }
        return maxLen;
    }
}

