class Solution:
    def longestSubarray(self, nums: list[int], limit: int) -> int:
        max_len = 0
        n = len(nums)
        for i in range(n):
            low = high = nums[i]
            for j in range(i, n):
                low = min(low, nums[j])
                high = max(high, nums[j])
                if high - low <= limit:
                    max_len = max(max_len, j - i + 1)
                else:
                    break
        return max_len

